public static RMarketSignalLog calculate(
    RMarketSubAccount     _subAccount,
    RMarketStrategySignal _action,
    RMarketTimestamp      _tsCursor)
{
    RMarketSignalTrace signalTrace = new RMarketSignalTrace();
    RMarketSignalResult result;
    str description;
    boolean signal;
    int infologStartLine;

    if (appl.ttsLevel())
        throw error("Signal calculation requires TTS level 0.");

    infologStartLine = infologLine();

    try
    {
        ttsbegin;

        signal = _action.calcSignal(
        _subAccount, _tsCursor, signalTrace);

        ttscommit;

        result = signal ? RMarketSignalResult::Triggered : RMarketSignalResult::NotTriggered;

        description = signalTrace.description();
    }
    catch (Exception::Error)
    {
        result = RMarketSignalResult::Error;

        description = RMarketSignalCalc::getInfologText(infologStartLine)
            + '\n'
            + signalTrace.description();
    }

    return RMarketSignalLog::putRecord(
        _subAccount.SubAccountId,
        _action.RecId,
        _tsCursor,
        result,
        description);
}

private static str getInfologText(int _startLine)
{
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct messageStruct;
    int endLine = infologLine();
    str ret;

    if (endLine > _startLine)
    {
        enumerator = SysInfologEnumerator::newData(infolog.copy(_startLine + 1, endLine));

        while (enumerator.moveNext())
        {
            messageStruct = new SysInfologMessageStruct(enumerator.currentMessage());

            if (ret)
                ret += '\n';

            ret += messageStruct.message();
        }
    }

    if (!ret)
        ret = "Signal calculation failed.";

    return ret;
}

public static boolean canCalculate(
    RMarketSubAccountId _subAccountId,
    RefRecId            _actionRecId,
    RMarketTimestamp    _timestamp)
{
    RMarketSignalLog signalLog;
    boolean ret = false;

    signalLog = RMarketSignalLog::findCompleted(_subAccountId, _actionRecId, _timestamp);

    if (!signalLog.RecId)
    {
        ret = RMarketSignalLog::countErrors(
            _subAccountId,
            _actionRecId,
            _timestamp) < #MaxAttempts;
    }

    return ret;
}

public static int calculateSubAccount(
    RMarketSubAccount _subAccount,
    RMarketTimestamp  _tsCursor)
{
    RMarketStrategy       strategy;
    RMarketStrategySignal action;
    RMarketTimestamp      signalTimestamp;
    int                   calculated;

    if (appl.ttsLevel())
        throw error("Signal calculation requires TTS level 0.");

    if (!_subAccount.RecId)
        throw error("Subaccount must be specified.");

    if (!_tsCursor)
        throw error("Timestamp must be specified.");

    strategy = RMarketStrategy::find(_subAccount.StrategyId);

    if (!strategy.RecId)
        throw error(strFmt("Strategy %1 not found.", _subAccount.StrategyId));

    signalTimestamp = RMarketUtil::calculateCandleTimestamp(_tsCursor, strategy.Interval);

    while select action
        order by action.Num
        where action.StrategyId == strategy.StrategyId
           && action.Active     == NoYes::Yes
    {
        if (RMarketSignalCalc::canCalculate(
            _subAccount.SubAccountId,
            action.RecId,
            signalTimestamp))
        {
            RMarketSignalCalc::calculate(
                _subAccount,
                action,
                signalTimestamp);

            calculated++;
        }
    }

    return calculated;
}
